"""English-only enrollment with separately recorded terms and privacy acknowledgment."""

import secrets
from .customer_credits import WELCOME_CREDITS
from .customer_workspace_pearl import pearl_response
from fastapi.responses import HTMLResponse
from .workflow_publication_service import no_store


def page_for():
    nonce = secrets.token_urlsafe(24)
    html = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Review your Free workspace plan, credits and enrollment choices."><title>Workspace plan and credits | Agent Concierge</title><style nonce="NONCE">
:root{font:16px system-ui;color-scheme:light dark;--bg:light-dark(#f5f7fb,#101620);--card:light-dark(white,#192438);--fg:light-dark(#17253b,#e8f0ff);--line:#8191ac55}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg)}main{max-width:900px;margin:auto;padding:32px}section{padding:24px;border:1px solid var(--line);border-radius:20px;background:var(--card);margin:20px 0}p{line-height:1.65}label{display:block;margin:18px 0}button{font:inherit;padding:12px 18px;border:1px solid var(--line);border-radius:12px;background:var(--card);color:inherit;cursor:pointer}button:disabled{opacity:.5}a{color:inherit}svg{height:24px;width:24px;vertical-align:middle}li{line-height:1.7}:focus-visible{outline:3px solid #77a7ff;outline-offset:3px}[hidden]{display:none!important}@media(max-width:600px){main{padding:18px}section{padding:18px}}</style></head><body><main><a href="/customer/organizations">Your workspace</a><h1><svg class="lucide lucide-coins" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="8" cy="8" r="6"/><path d="M18.1 9.9a6 6 0 1 1-8.2 8.2M7 6h1v4m9 4h1v4"/></svg> Workspace plan and credits</h1><p id="status" role="status" aria-live="polite">Checking your current plan.</p><section><h2>Free plan</h2><p>New accounts receive WELCOME_CREDITS credits once. Create workflows from natural language with AI, review the connections, then test and download your app.</p><p><strong id="balance">Checking credits…</strong></p><details class="context-help" id="credit-balance-help"><summary>How your balance works</summary><div class="context-help-body"><p id="credit-balance-basis">Existing balances keep their earlier grants and adjustments. Credits belong to your signed-in account across its workspaces. Your balance includes grants, credit adjustments and workflow usage. Expand credit history to review the changes.</p></div></details><p>Paid plans, automatic billing, paid conversion and credit top-ups: Coming soon. Joining today creates no charges. Future paid features require separate terms and your explicit authorization.</p><button disabled>Top up credits · Coming soon</button></section><section><h2>Workspace credit terms</h2><p id="terms"></p><p>Read the <a href="/#tos" target="_blank" rel="noopener">service Terms</a> and <a href="/#privacy" target="_blank" rel="noopener">Privacy notice</a>. Contact <a href="/new/en/contact.html">Contact support</a> for account or credit questions.</p><p id="privacy"></p><form id="enroll" hidden><label><input id="terms-check" type="checkbox" required>I agree to the service Terms and Workspace credit terms above.</label><label><input id="privacy-check" type="checkbox" required>I have read the Privacy notice and workspace data use explanation.</label><label><input id="adult-check" type="checkbox" required>I am at least 18, legally able to accept these terms and authorized to act for any organization I represent.</label><p>Enrollment does not sign you up for advertising. AI input sharing and agent execution each require their own review.</p><button id="join" disabled>Join the Free plan</button></form><div id="active" hidden><p><a class="workspace-start-link" href="/customer/organizations">Continue to your workflows</a></p><p>Your enrollment is active. You can close it at any time; this stops new saves and downloads. Existing records and used credits remain recorded.</p><label><input id="close-check" type="checkbox">I want to close my Free plan enrollment.</label><button id="close" disabled>Close enrollment</button></div></section><section><h2>Recent credit history</h2><p>Up to 100 entries, newest first. Earlier activity can also contribute to your current balance. Times are shown in UTC.</p><ul id="history"></ul></section></main><script nonce="NONCE">
const $=id=>document.getElementById(id);let csrf='',credits=null,busy=false;
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(body===undefined?15000:90000),headers:body===undefined?{}:{'Content-Type':'application/json','X-Customer-CSRF':csrf},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error();return r.json()}
function sync(){for(const id of ['terms-check','privacy-check','adult-check','close-check'])$(id).disabled=busy||!credits||!csrf;$('join').disabled=busy||!credits||!csrf||credits?.enrolled||credits?.status==='suspended'||!['terms-check','privacy-check','adult-check'].every(id=>$(id).checked);$('close').disabled=busy||!credits||!csrf||!credits?.enrolled||!$('close-check').checked}
async function load(){credits=(await api('/api/customer-credits')).credits;$('terms').textContent=credits.terms;$('privacy').textContent=credits.privacy;$('balance').textContent=credits.balance.toLocaleString('en-US')+' credits · '+({active:'Plan active',not_enrolled:'Not enrolled',closed:'Enrollment closed',suspended:'Plan suspended'}[credits.status]||'Review plan status');$('enroll').hidden=credits.enrolled;$('active').hidden=!credits.enrolled;$('history').replaceChildren();for(const item of credits.history){const li=document.createElement('li');li.textContent=new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'}).format(new Date(item.created*1000))+' UTC · '+item.action.replaceAll('_',' ')+' · '+(item.delta>0?'+':'')+item.delta.toLocaleString('en-US')+' · Balance '+item.balance.toLocaleString('en-US');$('history').append(li)}if(!credits.history.length){const li=document.createElement('li');li.textContent='No credit activity yet.';$('history').append(li)}for(const id of ['terms-check','privacy-check','adult-check','close-check'])$(id).checked=false;sync()}
async function work(fn){if(busy)return;busy=true;const finish=window.workspaceUI.begin('Processing your reviewed request…');sync();try{await window.workspaceUI.paint();await fn();await load();$('status').textContent='Your plan and credit history are current.'}catch{$('status').textContent='The change could not be confirmed. Refresh this page to review your current plan before trying again.'}finally{finish();busy=false;sync()}}
$('enroll').onsubmit=e=>{e.preventDefault();if($('join').disabled)return;work(()=>api('/api/customer-credits/enroll',{version:credits.version,digest:credits.digest,terms_accepted:true,privacy_acknowledged:true,adult_authority:true}))};$('close').onclick=()=>{if(!$('close').disabled)work(()=>api('/api/customer-credits/close',{revision:credits.revision,confirm:'CLOSE'}))};for(const id of ['terms-check','privacy-check','adult-check','close-check'])$(id).onchange=sync;
sync();
(async()=>{try{csrf=(await api('/api/customer-auth/session')).session.csrf_token;document.dispatchEvent(new Event('workspace-session-ready'));await load();$('status').textContent=credits.enrolled?'Your plan and credit history are current.':'Review your plan and choose whether to enroll.'}catch{$('status').textContent='Sign in to review your plan.';const a=document.createElement('a');a.href='/customer/sign-in';a.textContent='Sign in';$('status').append(' ',a)}})();
</script></body></html>""".replace("NONCE", nonce).replace("WELCOME_CREDITS", str(WELCOME_CREDITS))
    return pearl_response(HTMLResponse(
        html,
        headers={
            **no_store(),
            "X-Robots-Tag": "noindex,noarchive",
            "Referrer-Policy": "no-referrer",
            "X-Content-Type-Options": "nosniff",
            "Content-Security-Policy": "default-src 'none'; script-src 'nonce-"
            + nonce
            + "'; style-src 'nonce-"
            + nonce
            + "'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'",
        },
    ),nonce,section="credits",workspace=None,auth=False)
